use ide_db::{apply_change::Change, root_database::RootDatabase};
use std::{
    hash::{Hash, Hasher},
    time::Instant,
};
fn main() {
    let source: String =
        (0..500).map(|i| format!("function f{i}(x : int) -> int = (x + 1) + 1\n")).collect();
    let mut db = RootDatabase::default();
    let id = base_db::FileId::from_raw(0);
    let mut change = Change::new();
    change.change_file(id, source);
    db.apply_change(change);
    let file = db.files().file_text(id).unwrap();
    let root = syntax::parse_query::parse_file(&db, file).syntax_node().unwrap();
    let mut times = Vec::new();
    let mut hash = 0;
    let mut count = 0;
    for i in 0..25 {
        let start = Instant::now();
        let finder = ide_ssr::MatchFinder::new(&db, file, 0, "$x + 1 ==>> $x").unwrap();
        let edits = finder.edits_for_tree_in_ranges(&root, file, &[]);
        if i >= 5 {
            times.push(start.elapsed().as_nanos());
        }
        let mut h = std::collections::hash_map::DefaultHasher::new();
        for edit in &edits {
            edit.range.hash(&mut h);
            edit.new_text.hash(&mut h);
        }
        if i > 0 {
            assert_eq!(hash, h.finish());
        }
        hash = h.finish();
        count = edits.len();
        assert_eq!(count, 500);
    }
    times.sort();
    println!(
        "{}",
        serde_json::json!({"count":count,"digest":hash,"p50_ns":times[10],"p95_ns":times[18]})
    );
}

