use ide_db::root_database::RootDatabase;
use std::{sync::Arc, time::Instant};
fn main() {
    let mut report = Vec::new();
    for count in [20, 400] {
        for end in ["foo(va$0lue)", "foo($0", "if $0 then 1 else 2"] {
            let mut source: String =
                (0..count).map(|i| format!("function f{i}(x : int) -> int = x + 1\n")).collect();
            source.push_str(&format!("function target(value : int) -> int = {end}\n"));
            let offset = source.find("$0").unwrap();
            source.replace_range(offset..offset + 2, "");
            let db = RootDatabase::default();
            let file = base_db::FileText::new(
                &db,
                Arc::from(source.as_str()),
                base_db::FileId::from_raw(0),
            );
            let parsed = syntax::parse_query::parse_file(&db, file);
            let mut baseline = Vec::new();
            let mut direct = Vec::new();
            for i in 0..40 {
                let mut a = || {
                    let t = Instant::now();
                    let root = parsed
                        .reparse(
                            syntax::TextRange::empty((offset as u32).into()),
                            "sailCompletionMarker",
                        )
                        .syntax_node()
                        .unwrap();
                    if i >= 10 {
                        baseline.push(t.elapsed().as_nanos());
                    }
                    root
                };
                let mut b = || {
                    let t = Instant::now();
                    let mut edited = source.clone();
                    edited.insert_str(offset, "sailCompletionMarker");
                    let (root, _) = syntax::parse_text_with_fixities(&edited, Default::default());
                    if i >= 10 {
                        direct.push(t.elapsed().as_nanos());
                    }
                    root
                };
                let (a, b) = if i % 2 == 0 {
                    (a(), b())
                } else {
                    let b = b();
                    (a(), b)
                };
                assert_eq!(a.green(), b.green());
            }
            baseline.sort();
            direct.sort();
            report.push(serde_json::json!({"functions":count,"case":end,"baseline_p50_ns":baseline[15],"direct_p50_ns":direct[15],"same_tree":true}));
        }
    }
    println!("{}", serde_json::to_string_pretty(&report).unwrap());
}

