use ide_db::{apply_change::Change, root_database::RootDatabase};
use std::time::Instant;
fn main() {
    let declarations: String =
        (0..300).map(|i| format!("struct S{i} = {{ value : int, flag : bool }}\n")).collect();
    let mut db = RootDatabase::default();
    let id = base_db::FileId::from_raw(0);
    let mut times = Vec::new();
    for i in 0..45 {
        let mut edit = Change::new();
        edit.set_workspace_files(vec![id]);
        edit.change_file(
            id,
            format!("infixl 6 +\n{declarations}function f(x : int) -> int = x + {i}\n"),
        );
        let t = Instant::now();
        db.apply_change(edit);
        if i >= 5 {
            times.push(t.elapsed().as_nanos());
        }
        let file = db.files().file_text(id).unwrap();
        let expected =
            hir::def_query::file_item_tree(&db, file).as_ref().unwrap().build_fixity_context();
        assert_eq!(base_db::WorkspaceFixities::try_get(&db).unwrap().fixities(&db), &expected);
    }
    times.sort();
    println!(
        "{}",
        serde_json::json!({"p50_ns":times[20],"p95_ns":times[37],"edits":40,"fixities_equal":true})
    );
}

